<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'

const emit = defineEmits<{ navigate: [page: 'home'] }>()
type Slide = { key: string; section: string; title: string; description: string; tip: string; visual: 'home' | 'applications' | 'calendar' | 'mail' | 'stats' | 'interview' | 'team' }
const slides: Slide[] = [
  { key: 'home', section: '从首页开始', title: '先看主页，掌握求职节奏', description: '主页把最近的面试安排、待处理事项和求职动态放在一起。登录后先扫一眼今天和接下来几天的安排，重要节点就不容易漏掉。', tip: '建议先添加正在跟进的岗位，再把已经确定的面试时间记入日程。', visual: 'home' },
  { key: 'applications', section: '管理机会', title: '每个岗位一条进度时间线', description: '在「投递记录」中维护公司、岗位、渠道和当前招聘阶段。收到进展后更新状态，系统会把关键变化串成时间线，方便回看每个机会走到了哪一步。', tip: '可用备注补充联系人、薪资沟通和下一步待办等信息。', visual: 'applications' },
  { key: 'calendar', section: '安排时间', title: '把面试和待办排进日程', description: '日程支持时间点和时间段两种安排，也可以记录面试轮次、地点或会议链接、备注和面试回顾。日历与首页时间轴会汇总你的安排。', tip: '面试结束后，在编辑日程中补上面试回顾，之后就能在面试总结里整理复习。', visual: 'calendar' },
  { key: 'mail', section: '减少手工录入', title: '让招聘邮件进入工作流', description: '配置邮箱客户端授权后，CareerFlow 可以收取招聘邮件并识别公司、岗位、面试时间和流程变化等信息，帮你把邮件内容转成后续可处理的事项。', tip: '识别结果应先检查再确认；邮箱设置中可以查看连接状态与待处理邮件。', visual: 'mail' },
  { key: 'stats', section: '回顾进度', title: '用统计看求职过程', description: '统计页面从阶段、渠道和时间等角度汇总投递情况，让你快速了解机会分布和近期进展，也能发现需要调整的环节。', tip: '持续维护投递阶段，统计结果会更完整、更有参考价值。', visual: 'stats' },
  { key: 'interview', section: '积累经验', title: '把真实面试变成复习材料', description: '在完成的面试日程里记录问题和回顾，再到「面试总结」按项目经历、通用知识点和其他问题整理。相似问法会归纳到一起，并生成详细学习讲解。', tip: '个人主页可以补充教育、实习和项目经历，项目类讲解会结合对应经历生成。', visual: 'interview' },
  { key: 'team', section: '一起协作', title: '与小组成员共享求职进度', description: '创建或加入小组后，可和成员共同查看小组求职进度与日程。个人记录和小组协作各自保留，适合和同学互相提醒、交流经验。', tip: '使用小组功能前，请确认当前记录的可见范围符合你的需要。', visual: 'team' }
]
const index = ref(0)
const slide = computed(() => slides[index.value])
const progress = computed(() => ((index.value + 1) / slides.length) * 100)
function goTo(next: number) { index.value = Math.min(slides.length - 1, Math.max(0, next)) }
function onKeydown(event: KeyboardEvent) {
  if (event.altKey || event.ctrlKey || event.metaKey || event.target instanceof HTMLElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(event.target.tagName)) return
  if (event.key === 'ArrowRight') { event.preventDefault(); goTo(index.value + 1) }
  if (event.key === 'ArrowLeft') { event.preventDefault(); goTo(index.value - 1) }
}
onMounted(() => window.addEventListener('keydown', onKeydown))
onBeforeUnmount(() => window.removeEventListener('keydown', onKeydown))
</script>

<template>
  <div class="guide-page" aria-labelledby="guide-title">
    <header class="guide-topline">
      <button type="button" class="guide-back" @click="emit('navigate', 'home')"><span aria-hidden="true">←</span> 返回主页</button>
      <span class="guide-kicker">CAREFLOW 使用指南</span>
      <span class="guide-count">{{ String(index + 1).padStart(2, '0') }} <i>/</i> {{ String(slides.length).padStart(2, '0') }}</span>
    </header>

    <div class="guide-progress" role="progressbar" :aria-valuenow="index + 1" :aria-valuemin="1" :aria-valuemax="slides.length" :aria-label="`第 ${index + 1} 页，共 ${slides.length} 页`"><span :style="{ width: `${progress}%` }"></span></div>

    <Transition name="guide-slide" mode="out-in">
      <article :key="slide.key" class="guide-slide">
        <section class="guide-copy">
          <span class="guide-section"><i>{{ String(index + 1).padStart(2, '0') }}</i>{{ slide.section }}</span>
