          <p class="guide-description">{{ slide.description }}</p>
          <p class="guide-tip"><span aria-hidden="true">✦</span><span>{{ slide.tip }}</span></p>
          <div class="guide-controls">
            <button type="button" class="arrow-button previous" :disabled="index === 0" aria-label="上一页" @click="goTo(index - 1)"><span aria-hidden="true">←</span></button>
            <div class="guide-dots" aria-label="跳转到指引页面"><button v-for="(item, itemIndex) in slides" :key="item.key" type="button" :class="{ active: index === itemIndex }" :aria-label="`第 ${itemIndex + 1} 页：${item.section}`" :aria-current="index === itemIndex ? 'step' : undefined" @click="goTo(itemIndex)"></button></div>
            <button v-if="index < slides.length - 1" type="button" class="arrow-button next" aria-label="下一页" @click="goTo(index + 1)"><span aria-hidden="true">→</span></button>
            <button v-else type="button" class="finish-button" @click="emit('navigate', 'home')">开始使用 <span aria-hidden="true">↗</span></button>
          </div>
          <p class="keyboard-hint"><kbd>←</kbd><kbd>→</kbd> 也可以用键盘翻页</p>
        </section>

        <section class="guide-art" :class="`visual-${slide.visual}`" aria-label="功能示意图">
          <div class="art-window">
            <div class="art-window-bar"><span class="brand-mark">C</span><strong>CareerFlow</strong><span class="window-dots"><i></i><i></i><i></i></span></div>
